<script setup lang="ts">
import { computed, onMounted } from 'vue'
import { Bell, CheckCircle2, Flame, MapPin, ShieldCheck } from 'lucide-vue-next'
import StatusBadge from '../components/common/StatusBadge.vue'
import { useCitizenReportStore } from '../stores/citizen-report.store'
import { useIncidentStore } from '../stores/incident.store'

const reportStore = useCitizenReportStore(); const incidentStore = useIncidentStore()
const recentReports = computed(()=>reportStore.reports.slice().sort((a,b)=>new Date(b.createdAt).getTime()-new Date(a.createdAt).getTime()).slice(0,2))
const nearbyActive = computed(()=>incidentStore.incidents.filter((item)=>!['CERRADA','FINALIZADA','CANCELADA','FALSA_ALARMA'].includes(item.status)).length)
onMounted(async()=>{await Promise.all([reportStore.fetchReports(),incidentStore.fetchIncidents()])})
</script>
<template><div class="mx-auto max-w-5xl space-y-6"><section class="rounded-3xl border border-orange-200 bg-gradient-to-br from-[#fff8f1] to-white p-6 shadow-sm sm:p-8"><div class="flex flex-col gap-6 lg:flex-row lg:items-center lg:justify-between"><div class="max-w-2xl"><p class="text-[10px] font-semibold uppercase tracking-[0.24em] text-orange-500">ALERTA · Prevención de Incendios</p><h2 class="mt-3 text-3xl font-semibold text-slate-900">Información clara para actuar a tiempo</h2><p class="mt-3 text-sm leading-6 text-slate-600">Reporta una situación de riesgo, revisa el estado de tus reportes y consulta recomendaciones generales de emergencia.</p></div><RouterLink to="/ciudadano/reportar" class="inline-flex items-center justify-center gap-2 rounded-2xl bg-[#f24a23] px-6 py-4 text-base font-semibold text-white shadow-lg shadow-orange-100"><Flame class="h-5 w-5"/> Reportar incendio</RouterLink></div></section><section class="grid gap-4 md:grid-cols-3"><article class="rounded-2xl border border-emerald-200 bg-emerald-50 p-5"><CheckCircle2 class="h-6 w-6 text-emerald-700"/><p class="mt-4 text-xs font-semibold uppercase tracking-[0.16em] text-emerald-700">Estado de zona</p><p class="mt-2 text-xl font-semibold text-slate-900">Monitoreo activo</p><p class="mt-1 text-sm text-slate-600">Información demostrativa de La Paz.</p></article><RouterLink to="/ciudadano/notificaciones" class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><Bell class="h-6 w-6 text-orange-500"/><p class="mt-4 text-xs font-semibold uppercase tracking-[0.16em] text-slate-500">Notificaciones</p><p class="mt-2 text-xl font-semibold text-slate-900">{{ nearbyActive }} eventos activos</p><p class="mt-1 text-sm text-slate-600">Consulta avisos de demostración.</p></RouterLink><RouterLink to="/ciudadano/instrucciones" class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><ShieldCheck class="h-6 w-6 text-sky-800"/><p class="mt-4 text-xs font-semibold uppercase tracking-[0.16em] text-slate-500">Ayuda</p><p class="mt-2 text-xl font-semibold text-slate-900">Instrucciones</p><p class="mt-1 text-sm text-slate-600">Qué hacer ante una emergencia.</p></RouterLink></section><section class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div class="flex items-center justify-between"><div><p class="text-[10px] font-semibold uppercase tracking-[0.18em] text-slate-500">Seguimiento</p><h3 class="mt-1 text-lg font-semibold text-slate-900">Tus reportes recientes</h3></div><RouterLink to="/ciudadano/mis-reportes" class="text-sm font-semibold text-orange-600">Ver todos</RouterLink></div><div class="mt-4 grid gap-3 md:grid-cols-2"><article v-for="report in recentReports" :key="report.id" class="rounded-xl border border-slate-200 bg-slate-50 p-4"><div class="flex items-center justify-between gap-2"><span class="text-xs font-semibold text-slate-500">{{ report.id }}</span><StatusBadge :state="report.status" :tone="report.status==='VALIDADO'?'success':report.status==='DESCARTADO'?'danger':'warning'">{{ report.status.replaceAll('_',' ') }}</StatusBadge></div><p class="mt-2 flex items-center gap-2 font-medium text-slate-900"><MapPin class="h-4 w-4 text-orange-500"/>{{ report.ubicacion }}</p><p class="mt-1 line-clamp-2 text-sm text-slate-600">{{ report.descripcion }}</p></article><p v-if="recentReports.length===0" class="text-sm text-slate-500">Todavía no realizaste reportes.</p></div></section></div></template>
